pub struct Invoice {
    pub amount: u64,
}

pub struct Invoice { amount: u64 }
impl Invoice { pub fn total(&self) -> u64 { self.amount } pub fn issue(&mut self) -> Result<(), IssueError> { Ok(()) } }
pub enum IssueError { AlreadyIssued }

mod errors { pub enum IssueError { AlreadyIssued } }
pub use errors::IssueError as Rejected;
pub type Outcome<T> = core::result::Result<T, Rejected>;
pub struct Invoice; impl Invoice { pub fn issue(&mut self) -> Outcome<()> { Ok(()) } }
